/// <summary>
/// API method for transfering Unit record
/// </summary>
/// <param name = "_record">json record</param>
/// <returns>API service response</returns>
public NDXServiceResponse transferUnitRecord(str _record)
{
    System.Exception ex;
    NDXServiceResponse response = new NDXServiceResponse();
    response .parmSuccess(false);

    if(_record != null)
    {
        UnitOfMeasure lUnitOfMeasure;

        try
        {
            Niedax.Units.UnitRecord record = Niedax.Units.UnitRecord::deserialize(_record);

            if(record)
            {
                lUnitOfMeasure = UnitOfMeasure::findOrCreateByObject(record);
            }

            if(lUnitOfMeasure.RecId == 0)
            {
                throw error('UnitOfMeasure record does not exist');
            }

            message = strFmt("UnitOfMeasure %1 inserted on %2", record.UnitId, this.environment);
            response.parmSuccess(true);
            response.parmRecId(lUnitOfMeasure.RecId);
            response.parmMessage(message);

        }
        catch (ex)
        {
            response.parmSuccess(false);
            response.parmMessage('UnitOfMeasure transfer process error: ' + ex.Message);
        }
    }

    return response;
}

