public NDXServiceResponse deleteUnitConvertRecord(str _itemId)
{
    System.Exception ex;
    System.Collections.IEnumerable unitConvertist;
    System.Collections.IEnumerator unitConvertistEnumartor;

    Niedax.Units.UnitConvertRecord record;
    NDXServiceResponse response = new NDXServiceResponse();
    response.parmSuccess(false);

    if(_itemId != null && _itemId != '')
    {
        UnitOfMeasureConversion lUnitOfMeasureConversion;

        try
        {
            ItemIdBase itemId = _itemId;
            InventTable lInventTable;
            EcoResProduct lEcoResProduct;

            select crosscompany lInventTable
                where lInventTable.ItemId == itemId;

            lEcoResProduct = ecoResProduct::find(lInventTable.Product);

            if(lEcoResProduct && lInventTable.NDXModelNumber == lEcoResProduct.DisplayProductNumber)
            {
                delete_from lUnitOfMeasureConversion
                    where lUnitOfMeasureConversion.Product == lInventTable.Product;

                message = strFmt("UnitOfMeasureConversion for %1 deleted on %2", itemId, this.environment);
            }
            else
            {
                message = strFmt("UnitOfMeasureConversion for %1 nothing to delete on %2", itemId, this.environment);
            }

            response.parmSuccess(true);
            response.parmRecId(lUnitOfMeasureConversion.RecId);
            response.parmMessage(message);

        }
        catch (ex)
        {
            response.parmSuccess(false);
            response.parmMessage('UnitOfMeasureConversion delete process error: ' + ex.Message);
        }
    }

    return response;
}
